VirtualTeachingPanel::VirtualTeachingPanel(wxWindow* parent,std::shared_ptr<VirtualSessionController> c,VirtualBoardPanel* board,wave::TraceViewPanel* waves):wxScrolledWindow(parent),controller_(std::move(c)),board_(board),waves_(waves){
    auto* layout=new wxBoxSizer(wxVERTICAL);auto* courses=new wxWrapSizer(wxHORIZONTAL);course_=new wxChoice(this,wxID_ANY);for(auto label:{"01 · LED 异常定位","02 · 相邻输出争用","03 · 按键计数鲁棒性","04 · 时钟与通信恢复"})course_->Append(wxString::FromUTF8(label));course_->SetSelection(0);courses->Add(course_,0,wxRIGHT|wxBOTTOM,FromDIP(5));auto* start=new wxButton(this,wxID_ANY,wxString::FromUTF8("开始盲测排障"));courses->Add(start,0,wxBOTTOM,FromDIP(5));layout->Add(courses,0,wxEXPAND|wxALL,FromDIP(6));
    start->Bind(wxEVT_BUTTON,[this](wxCommandEvent&){static const char* ids[]={"course-01-open-wire","course-02-bridge-contention","course-03-button-debounce","course-04-uart-clock-fault"};StartCourse(ids[course_->GetSelection()]);});
    auto* measurements=new wxWrapSizer(wxHORIZONTAL);left_=new wxTextCtrl(this,wxID_ANY,"pad.10",wxDefaultPosition,FromDIP(wxSize(150,-1)));right_=new wxTextCtrl(this,wxID_ANY,"led0.K",wxDefaultPosition,FromDIP(wxSize(150,-1)));measurements->Add(left_,0,wxRIGHT|wxBOTTOM,FromDIP(5));measurements->Add(right_,0,wxRIGHT|wxBOTTOM,FromDIP(5));auto* measure=new wxButton(this,wxID_ANY,wxString::FromUTF8("双端 Probe / 数字表"));measurements->Add(measure,0,wxRIGHT|wxBOTTOM,FromDIP(5));auto* explain=new wxButton(this,wxID_ANY,wxString::FromUTF8("STATE 逐步解释"));measurements->Add(explain,0,wxBOTTOM,FromDIP(5));layout->Add(measurements,0,wxEXPAND|wxALL,FromDIP(6));
    measure->Bind(wxEVT_BUTTON,[this](wxCommandEvent&){MeasurePair(left_->GetValue().ToStdString(wxConvUTF8),right_->GetValue().ToStdString(wxConvUTF8));});explain->Bind(wxEVT_BUTTON,[this](wxCommandEvent&){try{board_->InspectNode(left_->GetValue().ToStdString(wxConvUTF8));}catch(const std::exception& e){output_->ChangeValue(wxString::FromUTF8(e.what()));}});
    auto* hints=new wxWrapSizer(wxHORIZONTAL);hint_=new wxChoice(this,wxID_ANY);for(auto level:{"L1","L2","L3","L4"})hint_->Append(level);hint_->SetSelection(0);hints->Add(hint_,0,wxRIGHT|wxBOTTOM,FromDIP(5));auto* requestHint=new wxButton(this,wxID_ANY,wxString::FromUTF8("申请提示（逐级解锁）"));hints->Add(requestHint,0,wxRIGHT|wxBOTTOM,FromDIP(5));cause_=new wxTextCtrl(this,wxID_ANY,"wire.led0",wxDefaultPosition,FromDIP(wxSize(170,-1)));hints->Add(cause_,0,wxRIGHT|wxBOTTOM,FromDIP(5));cause_type_=new wxChoice(this,wxID_ANY);for(auto type:{"open","bridge","button_bounce","clock_stop"})cause_type_->Append(type);cause_type_->SetSelection(0);hints->Add(cause_type_,0,wxBOTTOM,FromDIP(5));layout->Add(hints,0,wxEXPAND|wxALL,FromDIP(6));requestHint->Bind(wxEVT_BUTTON,[this](wxCommandEvent&){RequestHint(hint_->GetStringSelection().ToStdString(wxConvUTF8));});
    auto* grading=new wxWrapSizer(wxHORIZONTAL);repair_=new wxTextCtrl(this,wxID_ANY,"{\"restore\":\"wire.led0\"}",wxDefaultPosition,FromDIP(wxSize(300,-1)));repair_->SetToolTip(wxString::FromUTF8("物理修复位置 restore；或已保存 RTL 文件 source。判题在可信侧实际编译与复测。"));grading->Add(repair_,0,wxRIGHT|wxBOTTOM,FromDIP(5));auto* choose=new wxButton(this,wxID_ANY,wxString::FromUTF8("选择修复 RTL"));grading->Add(choose,0,wxRIGHT|wxBOTTOM,FromDIP(5));auto* grade=new wxButton(this,wxID_ANY,wxString::FromUTF8("提交定位与修复 / 判题"));grading->Add(grade,0,wxBOTTOM,FromDIP(5));layout->Add(grading,0,wxEXPAND|wxALL,FromDIP(6));choose->Bind(wxEVT_BUTTON,[this](wxCommandEvent&){wxFileDialog file(this,wxString::FromUTF8("选择课程工作区内已保存的修复源码"),"","","RTL (*.sv;*.v)|*.sv;*.v",wxFD_OPEN|wxFD_FILE_MUST_EXIST);if(file.ShowModal()==wxID_OK)repair_->ChangeValue(wxString::FromUTF8(Json{{"source",file.GetPath().ToStdString(wxConvUTF8)}}.dump()));});grade->Bind(wxEVT_BUTTON,[this](wxCommandEvent&){try{SubmitGrade({{"location",cause_->GetValue().ToStdString(wxConvUTF8)},{"type",cause_type_->GetStringSelection().ToStdString(wxConvUTF8)}},Json::parse(repair_->GetValue().ToStdString(wxConvUTF8)));}catch(const std::exception& e){output_->ChangeValue(wxString::FromUTF8(e.what()));}});
    auto* capture=new wxWrapSizer(wxHORIZONTAL);capture_mode_=new wxChoice(this,wxID_ANY);capture_mode_->Append("virtual_probe / 运行中信号");capture_mode_->Append("virtual_rtl / 独立 RTL 参考轨");capture_mode_->SetSelection(0);capture->Add(capture_mode_,0,wxRIGHT|wxBOTTOM,FromDIP(5));auto* arm=new wxButton(this,wxID_ANY,wxString::FromUTF8("采集 16 个主时钟样本"));capture->Add(arm,0,wxRIGHT|wxBOTTOM,FromDIP(5));auto* readCapture=new wxButton(this,wxID_ANY,wxString::FromUTF8("读取采集"));capture->Add(readCapture,0,wxRIGHT|wxBOTTOM,FromDIP(5));auto* baseline=new wxButton(this,wxID_ANY,wxString::FromUTF8("保存为基线"));capture->Add(baseline,0,wxRIGHT|wxBOTTOM,FromDIP(5));auto* compare=new wxButton(this,wxID_ANY,wxString::FromUTF8("采集对比 / 首个分歧"));capture->Add(compare,0,wxBOTTOM,FromDIP(5));layout->Add(capture,0,wxEXPAND|wxALL,FromDIP(6));
    arm->Bind(wxEVT_BUTTON,[this](wxCommandEvent&){if(capture_mode_->GetSelection()==1){wxFileDialog file(this,wxString::FromUTF8("选择作为独立参考轨的 virtual.project.json"),"","virtual.project.json","JSON (*.json)|*.json",wxFD_OPEN|wxFD_FILE_MUST_EXIST);if(file.ShowModal()==wxID_OK)CaptureRtl(eda::platform::PathFromUtf8(file.GetPath().ToStdString(wxConvUTF8)));return;}ArmCapture({{"source","virtual_probe"},{"targets",Json::array({left_->GetValue().ToStdString(wxConvUTF8),right_->GetValue().ToStdString(wxConvUTF8)})},{"depth",16},{"pretrigger",2},{"decimation",1},{"trigger",{{"kind","mask_equal"},{"mask",0},{"value",0},{"count",3}}}});for(int i=0;i<20;++i)controller_->Queue({{"op","step"},{"mode","rising"}});ReadCapture();});readCapture->Bind(wxEVT_BUTTON,[this](wxCommandEvent&){ReadCapture();});baseline->Bind(wxEVT_BUTTON,[this](wxCommandEvent&){try{SetBaseline();}catch(const std::exception& e){output_->ChangeValue(wxString::FromUTF8(e.what()));}});compare->Bind(wxEVT_BUTTON,[this](wxCommandEvent&){try{CompareCapture();}catch(const std::exception& e){output_->ChangeValue(wxString::FromUTF8(e.what()));}});
    rtl_button_=arm;status_=new wxStaticText(this,wxID_ANY,"",wxDefaultPosition,wxDefaultSize,wxST_ELLIPSIZE_END|wxST_NO_AUTORESIZE);status_->SetMinSize(FromDIP(wxSize(0,22)));layout->Add(status_,0,wxEXPAND|wxALL,FromDIP(6));output_=new wxTextCtrl(this,wxID_ANY,"",wxDefaultPosition,FromDIP(wxSize(-1,220)),wxTE_MULTILINE|wxTE_READONLY|wxTE_DONTWRAP);layout->Add(output_,1,wxEXPAND|wxALL,FromDIP(6));SetSizer(layout);SetScrollRate(0,FromDIP(12));subscription_=controller_->Subscribe([this]{Update();});theme_=UiTheme::Subscribe([this]{ApplyTheme();});ApplyTheme();Update();
}
VirtualTeachingPanel::~VirtualTeachingPanel(){controller_->Unsubscribe(subscription_);rtl_builder_.Cancel();}
void VirtualTeachingPanel::StartCourse(const std::string& id){controller_->OpenTeaching(id);}
void VirtualTeachingPanel::MeasurePair(const std::string& left,const std::string& right){left_->ChangeValue(wxString::FromUTF8(left));right_->ChangeValue(wxString::FromUTF8(right));for(const auto& target:{left,right}){auto id="gui-probe-"+std::to_string(++probe_serial_);controller_->Queue({{"op","probe.attach"},{"probe_id",id},{"target",target}});controller_->Queue({{"op","probe.read"},{"probe_id",id}});}controller_->Queue({{"op",controller_->Frame().value("mode",std::string())=="student_blind_test"?"virtual.evidence.query":"evidence.query"}});}
void VirtualTeachingPanel::RequestHint(const std::string& level){controller_->Queue({{"op","teaching.hint.request"},{"level",level}});}
void VirtualTeachingPanel::SubmitGrade(const Json& cause,const Json& repair){Json ids=Json::array();for(const auto& item:evidence_)if(item.contains("evidence_id"))ids.push_back(item.at("evidence_id"));controller_->Queue({{"op","teaching.grade.submit"},{"root_cause",cause},{"evidence_ids",ids},{"repair",repair}});}
void VirtualTeachingPanel::ArmCapture(const Json& config){capture_=Json();capture_after_=controller_->ReplySequence()+1;controller_->Queue({{"op","capture.arm"},{"config",config}});}
void VirtualTeachingPanel::ReadCapture(){controller_->Queue({{"op","capture.read"}});}
void VirtualTeachingPanel::SetBaseline(){if(capture_.is_null() || capture_.at("armed")==true || capture_.at("samples").empty())throw std::runtime_error("E_CAPTURE_NOT_READY");baseline_=capture_;status_->SetLabel(wxString::FromUTF8("已保留独立采集基线"));}
Json VirtualTeachingPanel::CompareCapture(){if(baseline_.is_null() || capture_.is_null())throw std::runtime_error("E_CAPTURE_PAIR_REQUIRED");static uint64_t serial=0;auto folder=VirtualProjectSessionBuilder::FindRepository()/".work/virtual-wave-compare"/(std::to_string(wxGetProcessId())+"-"+std::to_string(++serial));comparison_=waves_->LoadVirtualCapturePair(baseline_,capture_,eda::platform::PathToUtf8(folder));output_->ChangeValue(wxString::FromUTF8(comparison_.dump(2)));return comparison_;}
void VirtualTeachingPanel::CaptureRtl(const std::filesystem::path& project){if(controller_->Frame().value("mode",std::string())=="student_blind_test")throw std::runtime_error("E_BLIND_REFERENCE_BUILD_DENIED");static uint64_t serial=0;auto repo=VirtualProjectSessionBuilder::FindRepository();auto folder=repo/".work/virtual-rtl-captures"/(std::to_string(wxGetProcessId())+"-"+std::to_string(++serial));rtl_result_={{"status","running"}};status_->SetLabel(wxString::FromUTF8("正在影子目录构建真实 RTL TraceBridge…"));rtl_builder_.Start({{"project",eda::platform::PathToUtf8(project)},{"output",eda::platform::PathToUtf8(folder)},{"build_dir",eda::platform::PathToUtf8(repo/"build-m0")},{"depth",16}},[this](Json result){rtl_result_=std::move(result);if(rtl_result_.value("status",std::string())=="passed"){capture_=rtl_result_.at("capture_snapshot");waves_->OpenTrace(rtl_result_.at("vcd"));}output_->ChangeValue(wxString::FromUTF8(rtl_result_.dump(2)));status_->SetLabel(wxString::FromUTF8(rtl_result_.value("status",std::string("failed"))));},"build_virtual_tracebridge.py");}
std::string VirtualTeachingPanel::OutputText()const{return output_->GetValue().ToStdString(wxConvUTF8);}
void VirtualTeachingPanel::Update(){const auto& frame=controller_->Frame();auto run=frame.value("run_id",std::string());if(run!=run_){rtl_builder_.Cancel();run_=run;evidence_=Json::array();capture_=Json();baseline_=Json();comparison_=Json();rtl_result_=Json();capture_after_=controller_->ReplySequence()+1;signature_.clear();output_->Clear();}bool blind=frame.value("mode",std::string())=="student_blind_test";if(blind)capture_mode_->SetSelection(0);capture_mode_->Enable(!blind);
    if(frame.contains("instruments") && frame.at("instruments").contains("evidence"))evidence_=frame.at("instruments").at("evidence");const auto& e=controller_->LatestReply("virtual.evidence.query");if(e.contains("measurements"))evidence_=e.at("measurements");const auto& r=controller_->LatestReply("capture.read");if(controller_->ReplySequence("capture.read")>=capture_after_ && r.contains("instrument_reply") && r.at("instrument_reply").contains("samples"))capture_=r.at("instrument_reply");Json displayed={{"measurements",evidence_}};if(frame.contains("student_workspace_source"))displayed["student_workspace_source"]=frame.at("student_workspace_source");if(frame.contains("instruments") && frame.at("instruments").contains("live"))displayed["live"]=frame.at("instruments").at("live");for(auto op:{"teaching.hint.request","teaching.grade.submit"})if(!controller_->LatestReply(op).empty())displayed[op]=controller_->LatestReply(op);auto signature=displayed.dump();if(signature!=signature_){signature_=signature;output_->ChangeValue(wxString::FromUTF8(displayed.dump(2)));}status_->SetLabel(wxString::FromUTF8(std::string(blind?"盲测：秘密规则不下发；仅测量、提示与判题":"调试：Probe / STATE13 / 虚拟采集对比")+" | evidence="+std::to_string(evidence_.size())));Layout();FitInside();}
void VirtualTeachingPanel::ApplyTheme(){const auto& p=UiTheme::Palette();SetBackgroundColour(p.bgPanel);for(auto* child:GetChildren()){child->SetBackgroundColour(p.surfaceOnPanel);child->SetForegroundColour(p.text1);child->SetFont(UiTheme::UiFont(this,UiTheme::TextSize::P12));}Refresh();}
